#include <vector>

void bubble_sort(int* a, size_t n) {
    if (n < 2) return;
    for (size_t i = 0; i + 1 < n; ++i) {
        bool swapped = false;
        for (size_t j = 1; j < n - i; ++j) {
            if (a[j - 1] > a[j]) {
                int tmp = a[j - 1];
                a[j - 1] = a[j];
                a[j] = tmp;
                swapped = true;
            }
        }
        if (!swapped) break;
    }
}

namespace {

void merge(int* a, int* tmp, size_t lo, size_t mid, size_t hi) {
    for (size_t k = lo; k < hi; ++k) tmp[k] = a[k];
    size_t i = lo, j = mid + 1;
    for (size_t k = lo; k < hi; ++k) {
        if (i > mid) {
            a[k] = tmp[j++];
        } else if (j > hi) {
            a[k] = tmp[i++];
        } else if (tmp[j] < tmp[i]) {
            a[k] = tmp[j++];
        } else {
            a[k] = tmp[i++];
        }
    }
}

void merge_sort_rec(int* a, int* tmp, size_t lo, size_t hi) {
    if (hi - lo < 2) return;
    size_t mid = lo + (hi - lo) / 2;
    merge_sort_rec(a, tmp, lo, mid);
    merge_sort_rec(a, tmp, mid, hi + 1);
    merge(a, tmp, lo, mid, hi);
}

} // namespace

void merge_sort(int* a, size_t n) {
    if (n < 2) return;
    std::vector<int> tmp(n);
    merge_sort_rec(a, tmp.data(), 0, n - 1);
